cypress_script:
describe('Multi-level dropdown navigation menu', () => {
  it('should navigate to the PDF download when clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('#menu').trigger('mouseover');
    cy.contains('PDF').click();
    cy.url().should('include', '/download/jqueryui/menu/menu.pdf');
  });

  it('should not allow interaction with the Disabled menu item', () => {
    cy.visit('https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('#menu').trigger('mouseover');
    cy.contains('Disabled').should('be.visible');
    cy.contains('Disabled').click();
    cy.url().should('not.include', 'Disabled');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Multi-level dropdown navigation menu', () => {
  test('should navigate to the PDF download when clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/jqueryui/menu');
    await page.hover('#menu');
    await page.click('text=PDF');
    await expect(page).toHaveURL(/.*download\/jqueryui\/menu\/menu.pdf/);
  });

  test('should not allow interaction with the Disabled menu item', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/jqueryui/menu');
    await page.hover('#menu');
    await expect(page.locator('text=Disabled')).toBeVisible();
    await page.locator('text=Disabled').click();
    await expect(page).not.toHaveURL(/.*Disabled/);
  });
});
